class Solution {
public:
    int tallestBillboard(vector<int>& rods) {
        int total = 0;
        for (int r : rods) total += r;
        int offset = total;
        vector<int> dp(2 * total + 1, -1);
        dp[offset] = 0;
        for (int r : rods) {
            vector<int> ndp = dp;
            for (int d = 0; d <= 2 * total; d++) {
                if (dp[d] < 0) continue;
                ndp[d + r] = max(ndp[d + r], dp[d] + r);
                ndp[d - r] = max(ndp[d - r], dp[d]);
            }
            dp = ndp;
        }
        return dp[offset];
    }
};
